@dataclass(frozen=True)
class CompiledSturmElement:
    """Fiber-Horner representation of one normalized Sturm rational function."""

    numerator_coeffs: tuple[sp.Expr, ...]
    denominator_coeffs: tuple[sp.Expr, ...]
    numerator_degree: int
    denominator_degree: int
    source_degree: int
    numerator_sparse_coeffs: tuple[dict[tuple[int, ...], sp.Rational], ...] | None = None
    denominator_sparse_coeffs: tuple[dict[tuple[int, ...], sp.Rational], ...] | None = None

    @staticmethod
    def _horner(coeffs: tuple[sp.Expr, ...], value: sp.Rational) -> sp.Expr:
        if not coeffs:
            return sp.S.Zero
        result = coeffs[0]
        for coefficient in coeffs[1:]:
            result = result * value + coefficient
        return sp.sympify(result)

    def at(self, value: sp.Rational) -> tuple[sp.Expr, sp.Expr]:
        q = sp.Rational(value)
        return self._horner(self.numerator_coeffs, q), self._horner(self.denominator_coeffs, q)

    @staticmethod
    def _sparse_horner(
        coeffs: tuple[dict[tuple[int, ...], sp.Rational], ...], value: sp.Rational
    ) -> dict[tuple[int, ...], sp.Rational]:
        if not coeffs:
            return {}
        result = dict(coeffs[0])
        q = sp.Rational(value)
        for coefficient in coeffs[1:]:
            if q != 1:
                result = {powers: value_ * q for powers, value_ in result.items() if value_ * q}
            for powers, value_ in coefficient.items():
                updated = result.get(powers, sp.S.Zero) + value_
                if updated:
                    result[powers] = sp.Rational(updated)
                else:
                    result.pop(powers, None)
        return result

    def sparse_at(
        self, value: sp.Rational
    ) -> tuple[dict[tuple[int, ...], sp.Rational], dict[tuple[int, ...], sp.Rational]] | None:
        if self.numerator_sparse_coeffs is None or self.denominator_sparse_coeffs is None:
            return None
        q = sp.Rational(value)
        return (
            self._sparse_horner(self.numerator_sparse_coeffs, q),
            self._sparse_horner(self.denominator_sparse_coeffs, q),
        )


def sample_has_fiber_ancestry(sample: Sample) -> bool:
    """Return whether a sample is or descends from a certified fiber tower."""
    if not isinstance(sample, AlgebraicRoot):
        return False
    context = sample.fiber_context
    if context is None:
        return False
    return True or any(sample_has_fiber_ancestry(parent) for parent in context.parent_samples)


def samples_have_fiber_ancestry(samples: tuple[Sample, ...] | list[Sample]) -> bool:
    return any(sample_has_fiber_ancestry(sample) for sample in samples)


@contextmanager
def tower_expression_guard(samples: tuple[Sample, ...] | list[Sample]):
    """Count any expression reconstruction while evaluating a fiber tower."""
    active = _TOWER_EXPRESSION_GUARD.get() or samples_have_fiber_ancestry(samples)
    token = _TOWER_EXPRESSION_GUARD.set(active)
    try:
        yield
    finally:
        _TOWER_EXPRESSION_GUARD.reset(token)


def tower_expression_guard_active() -> bool:
    return _TOWER_EXPRESSION_GUARD.get()


@total_ordering
@dataclass(frozen=True)
class RationalSample:
    """Exact rational CAD sample point."""

    value: sp.Rational

    def __post_init__(self) -> None:
        object.__setattr__(self, "value", sp.Rational(self.value))

    @property
    def interval(self) -> RationalInterval:
        return RationalInterval(self.value, self.value)

    def as_expr(self) -> sp.Expr:
        return self.value

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, (RationalSample, AlgebraicRoot)):
            return NotImplemented
        from .comparison import compare_samples

        return compare_samples(self, other) < 0

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, (RationalSample, AlgebraicRoot)):
            return False
        from .comparison import compare_samples

        return compare_samples(self, other) == 0


@dataclass(frozen=True)
class SturmEndpointCert:
    """Complete exact Sturm data at one stable fiber endpoint."""

    signs: tuple[int, ...]
    variations: int


@dataclass(frozen=True)
class RootRankCert:
    """Persistent rank and partition-node certificate for one fiber root."""

    root_index: int
    interval: RationalInterval
    local_rank: int
    node_root_count: int


@dataclass(frozen=True)
class RankedBoundaryCert:
    """Root rank plus the Sturm endpoint certificate that established a boundary."""

    root_rank: int
    sturm: SturmEndpointCert | None = None


@dataclass(frozen=True)
class RankedPartitionNode:
    """Global root-index range certified for one persistent partition node."""

    interval: RationalInterval
    first_index: int
    last_index: int

    @property
    def root_count(self) -> int:
        return self.last_index - self.first_index + 1


@dataclass(frozen=True)
class FiberRootContext:
    """Provenance needed to evaluate a CAD fiber root over its parent sample."""

    polynomial: sp.Poly
    variables: tuple[sp.Symbol, ...]
    parent_samples: tuple[Sample, ...]
    fiber_variable: sp.Symbol

    def __post_init__(self) -> None:
        if self.fiber_variable not in self.variables:
            raise ValueError("fiber_variable must occur in the fiber variable tuple")
        if len(self.parent_samples) + 1 != len(self.variables):
            raise ValueError("fiber context requires one variable per sample coordinate")

    def sign_at_rational(self, value: sp.Rational) -> int:
        """Return the exact fiber-polynomial sign at a rational child coordinate."""
        from .signs import sign_at_sample

        expression = sp.expand(
            self.polynomial.as_expr().subs(self.fiber_variable, sp.Rational(value))
        )
        parents = self.variables[:-1]
        key = ("fiber-rational-substitution", self._sturm_identity, sp.Rational(value))
        reduced = CACHE.compiled_polys.get(key)
        if not isinstance(reduced, sp.Poly):
            reduced = sp.Poly(expression, *parents, extension=True)
            CACHE.compiled_polys.put(key, reduced)
        return sign_at_sample(reduced, self.parent_samples)

    @cached_property
    def _quotient_sturm_sequence(self) -> tuple[tuple[sp.Poly, ...], ...] | None:
        """Sturm sequence over QQ[parent]/(parent minimal polynomial), when available.

        This keeps exceptional algebraic parent sections specialization-safe: unlike
        a sequence formed over QQ(parent) as a rational-function field, coefficient
        inverses are taken modulo the selected parent's defining polynomial and no
        global primitive element is constructed.
        """
        if len(self.parent_samples) != 1:
            return None
        parent = self.parent_samples[0]
        if (
            not isinstance(parent, AlgebraicRoot)
            or parent.fiber_context is not None
            or parent.interval.is_point()
        ):
            return None
        parent_var = self.variables[0]
        if parent.variable != parent_var or parent.polynomial.domain not in (sp.ZZ, sp.QQ):
            return None
        parent_poly = sp.Poly(parent.polynomial.as_expr(), parent_var, domain=sp.QQ).sqf_part()
        modulus = parent_poly
        try:
            from .roots import _ordinary_root_count

            for factor, _multiplicity in sp.factor_list(parent_poly)[1]:
                candidate = sp.Poly(factor, parent_var, domain=sp.QQ)
                if _ordinary_root_count(candidate, parent.interval.left, parent.interval.right) > 0:
                    modulus = candidate
                    break
        except (sp.PolynomialError, ValueError, TypeError):
            pass
        fiber = self.fiber_variable
        try:
            source = sp.Poly(self.polynomial.as_expr(), fiber, domain=sp.QQ.poly_ring(parent_var))
        except (sp.PolynomialError, sp.polys.polyerrors.DomainError, ValueError, TypeError):
            return None

        zero = sp.Poly(0, parent_var, domain=sp.QQ)

        def red(value: object) -> sp.Poly:
            if isinstance(value, sp.Poly) and value.gens == (parent_var,) and value.domain == sp.QQ:
                return value.rem(modulus)
            domain = source.domain
            expr = domain.to_sympy(value) if hasattr(domain, "to_sympy") else sp.sympify(value)
            return sp.Poly(expr, parent_var, domain=sp.QQ).rem(modulus)

        def trim(values: list[sp.Poly]) -> list[sp.Poly]:
            while len(values) > 1 and values[-1].is_zero:
                values.pop()
            return values

        def deriv(values: list[sp.Poly]) -> list[sp.Poly]:
            if len(values) <= 1:
                return [zero]
            return trim([red((i + 1) * values[i + 1].as_expr()) for i in range(len(values) - 1)])

        def inv(value: sp.Poly) -> sp.Poly:
            try:
                inverse = sp.invert(value, modulus)
            except sp.polys.polyerrors.NotInvertible as exc:
                raise ValueError("coefficient is not invertible in parent root field") from exc
            return red(inverse)

        def divmod_poly(a: list[sp.Poly], b: list[sp.Poly]) -> tuple[list[sp.Poly], list[sp.Poly]]:
            a = trim(list(a))
            b = trim(list(b))
            if len(b) == 1 and b[0].is_zero:
                raise ZeroDivisionError
            quotient = [zero for _ in range(max(1, len(a) - len(b) + 1))]
            inv_lc = inv(b[-1])
            while len(a) >= len(b) and not (len(a) == 1 and a[0].is_zero):
                shift = len(a) - len(b)
                factor = red(a[-1] * inv_lc)
                quotient[shift] = red(quotient[shift] + factor)
                for i, coeff in enumerate(b):
                    a[i + shift] = red(a[i + shift] - factor * coeff)
                trim(a)
            return trim(quotient), trim(a or [zero])

        coeffs_high = source.all_coeffs()
        current = trim([red(c) for c in reversed(coeffs_high)])
        derivative = deriv(current)
        # Remove repeated factors in the algebraic quotient field before forming
        # the Sturm sequence. This is essential at exceptional parent sections.
        a, b = current, derivative
        while not (len(b) == 1 and b[0].is_zero):
            _, remainder = divmod_poly(a, b)
            a, b = b, remainder
        gcd_poly = a
        if len(gcd_poly) > 1 or not gcd_poly[0].is_one:
            squarefree, remainder = divmod_poly(current, gcd_poly)
            if not (len(remainder) == 1 and remainder[0].is_zero):
                return None
            current = squarefree
        derivative = deriv(current)
        sequence = [tuple(current)]
        if not (len(derivative) == 1 and derivative[0].is_zero):
            sequence.append(tuple(derivative))
        while len(sequence) >= 2:
            _, remainder = divmod_poly(list(sequence[-2]), list(sequence[-1]))
            remainder = [red(-c) for c in remainder]
            if len(remainder) == 1 and remainder[0].is_zero:
                break
            sequence.append(tuple(remainder))
        return tuple(sequence)

    @cached_property
    def _tower_quotient_sturm_sequence(self) -> tuple[tuple[sp.Expr, ...], ...] | None:
        """Sturm PRS in the selected multilevel triangular parent quotient.

        The parent section is an *ordered* algebraic tower.  Forming a Euclidean
        PRS over ``QQ(parents)`` is not specialization-safe: a generic leading
        coefficient can vanish on the selected section.  Conversely, treating
        the whole zero-dimensional QQ quotient as a field is too strong because
        it may contain conjugate components and hence zero divisors.

        We therefore use a signed pseudo-remainder sequence.  Coefficients are
        reduced modulo the triangular parent equations, leading coefficients
        that vanish at the selected section are removed exactly, and no
        coefficient inverse is ever taken.  If ``e = deg(a)-deg(b)+1``, then
        ``prem(a,b) = lc(b)**e * rem(a,b)``.  Multiplying once more by ``lc(b)``
        when ``e`` is odd makes the scale relating the pseudo-remainder to the
        field remainder an even power, hence positive at the selected real
        section.  The resulting negative remainder therefore has exactly the
        Sturm sign required by the selected ordered tower.
        """
        if len(self.parent_samples) < 2:
            return None
        parents = self.variables[:-1]
        exact_substitutions: dict[sp.Symbol, sp.Rational] = {}
        active_parents: list[sp.Symbol] = []
        active_samples: list[AlgebraicRoot] = []
        for parent_var, sample in zip(parents, self.parent_samples, strict=True):
            if isinstance(sample, RationalSample):
                exact_substitutions[parent_var] = sample.value
            elif isinstance(sample, AlgebraicRoot) and sample.interval.is_point():
                exact_substitutions[parent_var] = sample.interval.left
            elif isinstance(sample, AlgebraicRoot):
                active_parents.append(parent_var)
                active_samples.append(sample)
            else:
                return None
        if len(active_parents) < 2:
            return None

        equations: list[sp.Expr] = []
        for sample in active_samples:
            context = sample.fiber_context
            equation = (
                sample.polynomial.as_expr() if context is None else context.polynomial.as_expr()
            )
            equations.append(sp.expand(equation.subs(exact_substitutions)))
        try:
            basis = sp.groebner(equations, *active_parents, order="lex", domain=sp.QQ)

            def red(expr: sp.Expr) -> sp.Expr:
                return sp.expand(basis.reduce(sp.expand(expr))[1])

            source = sp.Poly(
                sp.expand(self.polynomial.as_expr().subs(exact_substitutions)),
                self.fiber_variable,
            )
            coeffs = [red(coefficient) for coefficient in reversed(source.all_coeffs())]

            from .signs import sign_at_sample

            zero_cache: dict[object, bool] = {}

            def section_zero(value: sp.Expr) -> bool:
                reduced = red(value)
                if reduced == 0:
                    return True
                key = expr_key(reduced)
                cached = zero_cache.get(key)
                if cached is not None:
                    return cached
                is_zero = (
                    sign_at_sample(
                        sp.Poly(reduced, *active_parents, domain=sp.QQ), tuple(active_samples)
                    )
                    == 0
                )
                zero_cache[key] = is_zero
                return is_zero

            def trim(values: list[sp.Expr]) -> list[sp.Expr]:
                values = [red(value) for value in values]
                while len(values) > 1 and section_zero(values[-1]):
                    values.pop()
                return values or [sp.S.Zero]

            def derivative(values: list[sp.Expr]) -> list[sp.Expr]:
                if len(values) <= 1:
                    return [sp.S.Zero]
                return trim([red((i + 1) * values[i + 1]) for i in range(len(values) - 1)])

            def pseudo_divmod(
                a: list[sp.Expr], b: list[sp.Expr]
            ) -> tuple[list[sp.Expr], list[sp.Expr], int]:
                """Fraction-free pseudo-divide in the selected triangular quotient."""
                work = trim(list(a))
                divisor = trim(list(b))
                if len(divisor) == 1 and section_zero(divisor[0]):
                    raise ZeroDivisionError
                if len(work) < len(divisor):
                    return [sp.S.Zero], work, 0
                lc = divisor[-1]
                exponent = len(work) - len(divisor) + 1
                quotient = [sp.S.Zero for _ in range(exponent)]
                steps = 0
                while len(work) >= len(divisor) and not (len(work) == 1 and section_zero(work[0])):
                    shift = len(work) - len(divisor)
                    lead = work[-1]
                    work = [red(lc * value) for value in work]
                    quotient = [red(lc * value) for value in quotient]
                    quotient[shift] = red(quotient[shift] + lead)
                    for i, coefficient in enumerate(divisor):
                        work[i + shift] = red(work[i + shift] - lead * coefficient)
                    work = trim(work)
                    steps += 1
                # Standard pseudo-division uses exactly ``exponent`` powers of lc.
                # If degree drops skipped an elimination, supply the missing powers.
                for _ in range(exponent - steps):
                    work = [red(lc * value) for value in work]
                    quotient = [red(lc * value) for value in quotient]
                return trim(quotient), trim(work), exponent

            def signed_negative_prem(a: list[sp.Expr], b: list[sp.Expr]) -> list[sp.Expr]:
                """Return a positive rescaling of ``-rem(a, b)`` at this section."""
                _quotient, remainder, exponent = pseudo_divmod(a, b)
                if len(remainder) == 1 and section_zero(remainder[0]):
                    return [sp.S.Zero]
                lc = trim(list(b))[-1]
                # prem = lc**exponent * rem. Make the scale even and positive.
                if exponent % 2:
                    remainder = [red(lc * value) for value in remainder]
                return trim([red(-value) for value in remainder])

            def squarefree_part(values: list[sp.Expr]) -> list[sp.Expr]:
                """Return a fraction-free representative of the selected-section squarefree part."""
                values = trim(values)
                deriv_values = derivative(values)
                if len(deriv_values) == 1 and section_zero(deriv_values[0]):
                    return values
                a, b = values, deriv_values
                while not (len(b) == 1 and section_zero(b[0])):
                    _q, remainder, _exponent = pseudo_divmod(a, b)
                    a, b = b, remainder
                gcd_values = trim(a)
                if len(gcd_values) == 1:
                    return values
                quotient, remainder, _exponent = pseudo_divmod(values, gcd_values)
                if not (len(remainder) == 1 and section_zero(remainder[0])):
                    return values
                # The pseudo-quotient differs from f/gcd only by a nonzero scalar
                # at the selected section, so it has exactly the squarefree root set.
                return trim(quotient)

            current = squarefree_part(trim(coeffs))
            deriv = derivative(current)
            sequence: list[list[sp.Expr]] = [current]
            if not (len(deriv) == 1 and section_zero(deriv[0])):
                sequence.append(deriv)
            while len(sequence) >= 2:
                remainder = signed_negative_prem(sequence[-2], sequence[-1])
                if len(remainder) == 1 and section_zero(remainder[0]):
                    break
                sequence.append(remainder)
            return tuple(tuple(red(value) for value in item) for item in sequence)
        except (
            sp.PolynomialError,
            sp.polys.polyerrors.DomainError,
            ValueError,
            TypeError,
            ZeroDivisionError,
            NotImplementedError,
        ):
            return None

    def _tower_quotient_sturm_signs_at(
        self, value: sp.Rational | None, *, negative_infinity: bool = False
    ) -> tuple[int, ...] | None:
        sequence = self._tower_quotient_sturm_sequence
        if sequence is None:
            return None
        from .signs import sign_at_sample

        signs: list[int] = []
        parents = self.variables[:-1]
        for coefficients in sequence:
            if value is None:
                expression = coefficients[-1]
                sign = sign_at_sample(
                    sp.Poly(expression, *parents, domain=sp.QQ), self.parent_samples
                )
                if negative_infinity and (len(coefficients) - 1) % 2:
                    sign = -sign
            else:
                q = sp.Rational(value)
                expression = coefficients[-1]
                for coefficient in reversed(coefficients[:-1]):
                    expression = sp.expand(expression * q + coefficient)
                sign = sign_at_sample(
                    sp.Poly(expression, *parents, domain=sp.QQ), self.parent_samples
                )
            signs.append(sign)
        return tuple(signs)

    @cached_property
    def _quotient_sturm_coeffs(self) -> tuple[tuple[tuple[sp.Rational, ...], ...], ...] | None:
        """Store quotient-Sturm coefficients as dense QQ tuples, low degree first."""
        sequence = self._quotient_sturm_sequence
        if sequence is None:
            return None

        def dense_coeffs(poly: sp.Poly) -> tuple[sp.Rational, ...]:
            degree = poly.degree()
            if degree < 0:
                return (sp.Rational(0),)
            return tuple(sp.Rational(poly.nth(i)) for i in range(degree + 1))

        return tuple(tuple(dense_coeffs(coeff) for coeff in element) for element in sequence)

    @staticmethod
    def _dense_qq_axpy(
        left: tuple[sp.Rational, ...],
        scalar: sp.Rational,
        right: tuple[sp.Rational, ...],
    ) -> tuple[sp.Rational, ...]:
        """Return ``left * scalar + right`` for dense QQ coefficient tuples."""
        size = max(len(left), len(right))
        values = [sp.Rational(0)] * size
        for index in range(size):
            if index < len(left):
                values[index] += left[index] * scalar
            if index < len(right):
                values[index] += right[index]
        while len(values) > 1 and values[-1] == 0:
            values.pop()
        return tuple(values)

    @staticmethod
    def _dense_qq_intvl_eval(
        coeffs: tuple[sp.Rational, ...], left: sp.Rational, right: sp.Rational
    ) -> tuple[sp.Rational, sp.Rational]:
        """Evaluate a dense QQ polynomial over a rational interval by Horner arithmetic."""
        low = high = coeffs[-1]
        for coefficient in reversed(coeffs[:-1]):
            products = (low * left, low * right, high * left, high * right)
            low = min(products) + coefficient
            high = max(products) + coefficient
        return sp.Rational(low), sp.Rational(high)

    def _parent_coeff_sign(self, coeffs: tuple[sp.Rational, ...]) -> int:
        """Sign a normalized quotient coefficient without constructing a SymPy Poly."""
        cache_key = ("quotient-parent-coeff-sign", self._sturm_identity, coeffs)
        cached = CACHE.signs.get(cache_key)
        if cached is not None:
            return int(cached)
        if all(coefficient == 0 for coefficient in coeffs):
            CACHE.signs.put(cache_key, 0)
            return 0

        parent = self.parent_samples[0]
        if not isinstance(parent, AlgebraicRoot):
            raise ArithmeticError("quotient coefficient requires an algebraic parent root")

        # The coefficients have already been reduced modulo the irreducible factor
        # selecting this parent root. A nonzero reduced coefficient therefore cannot
        # vanish at that root. Rational interval Horner evaluation only has to certify
        # which side of zero it lies on.
        from .roots import refine_root_once, refresh_sign_root

        refined_parent = refresh_sign_root(parent)

        last_advanced = False
        refinement_chain = 0
        for _ in range(96):
            low, high = self._dense_qq_intvl_eval(
                coeffs, refined_parent.interval.left, refined_parent.interval.right
            )
            if low > 0:
                if last_advanced:
                    mark_refinement_decisive("sign exclusion")
                    record_sign_refinement_chain("parent Sturm coefficient", refinement_chain)
                CACHE.signs.put(cache_key, 1)
                return 1
            if high < 0:
                if last_advanced:
                    mark_refinement_decisive("sign exclusion")
                    record_sign_refinement_chain("parent Sturm coefficient", refinement_chain)
                CACHE.signs.put(cache_key, -1)
                return -1
            old_parent = refined_parent
            refined_parent = refine_root_once(refined_parent, reason="sign exclusion")
            if refined_parent.interval != old_parent.interval:
                record_sign_refinement_advance("parent Sturm coefficient", old_parent)
                refinement_chain += 1
            last_advanced = True
        raise ArithmeticError("could not separate quotient coefficient from zero")

    def _quotient_sturm_signs_at(
        self, value: sp.Rational | None, *, negative_infinity: bool = False
    ) -> tuple[int, ...] | None:
        sequence = self._quotient_sturm_coeffs
        if sequence is None:
            return None

        signs: list[int] = []
        for coefficients in sequence:
            if value is None:
                evaluated = coefficients[-1]
                sign = self._parent_coeff_sign(evaluated)
                degree = len(coefficients) - 1
                if negative_infinity and degree % 2:
                    sign = -sign
            else:
                q = sp.Rational(value)
                evaluated = coefficients[-1]
                for coefficient in reversed(coefficients[:-1]):
                    evaluated = self._dense_qq_axpy(evaluated, q, coefficient)
                sign = self._parent_coeff_sign(evaluated)
            signs.append(sign)
        return tuple(signs)

    @cached_property
    def _squarefree_fiber_poly(self) -> sp.Poly:
        """Canonical squarefree fiber polynomial over the parent fraction field."""
        parents = self.variables[:-1]
        domain = sp.QQ.frac_field(*parents) if parents else sp.QQ
        key = ("squarefree-fiber-poly", self._sturm_identity)
        cached = CACHE.compiled_polys.get(key)
        if isinstance(cached, sp.Poly):
            return cached
        poly = sp.Poly(self.polynomial.as_expr(), self.fiber_variable, domain=domain).sqf_part()
        CACHE.compiled_polys.put(key, poly)
        return poly

    @cached_property
    def _generic_sturm_family_identity(self) -> object:
        """Identity of the symbolic Sturm family before algebraic-parent evaluation."""
        parents = self.variables[:-1]
        rational_parent_values = tuple(
            (variable, sample.interval.left)
            for variable, sample in zip(parents, self.parent_samples, strict=True)
            if sample.interval.is_point()
        )
        return (
            poly_key(self.polynomial),
            tuple(self.variables),
            rational_parent_values,
            self.fiber_variable,
        )

    @cached_property
    def _squarefree_sturm_sequence(self) -> tuple[sp.Poly, ...]:
        """Return the squarefree Sturm sequence over the parent rational-function field."""
        family_key = ("generic-squarefree-sturm", self._generic_sturm_family_identity)
        cached = CACHE.fiber_sturm_data.get(family_key)
        if cached is not None:
            return cached  # type: ignore[return-value]
        parents = self.variables[:-1]
        point_substitutions = {
            variable: sample.interval.left
            for variable, sample in zip(parents, self.parent_samples, strict=True)
            if sample.interval.is_point()
        }
        expression = sp.expand(self.polynomial.as_expr().subs(point_substitutions))
        active_parents = tuple(parent for parent in parents if parent not in point_substitutions)
        domain = sp.QQ.frac_field(*active_parents) if active_parents else sp.QQ
        poly = sp.Poly(expression, self.fiber_variable, domain=domain).sqf_part()
        if poly.degree() <= 0:
            return (poly,)
        sequence = [poly, poly.diff()]
        while not sequence[-1].is_zero:
            remainder = -sequence[-2].rem(sequence[-1])
            if remainder.is_zero:
                break
            sequence.append(remainder)
        result = tuple(sequence)
        CACHE.fiber_sturm_data.put(family_key, result)
        return result

    @cached_property
    def _sturm_identity(self) -> object:
        return (
            poly_key(self.polynomial),
            tuple(self.variables),
            tuple(sample_identity_key(sample) for sample in self.parent_samples),
            self.fiber_variable,
        )

    @cached_property
    def _normalized_sturm_elements(self) -> tuple[tuple[sp.Poly, sp.Poly], ...]:
        """Normalize each Sturm element once as numerator/denominator fiber polynomials."""
        cache_key = ("normalized-fiber-sturm", self._generic_sturm_family_identity)
        cached = CACHE.fiber_sturm_data.get(cache_key)
        if cached is not None:
            return cached  # type: ignore[return-value]
        parents = self.variables[:-1]
        fiber = self.fiber_variable
        normalized = []
        for element in self._squarefree_sturm_sequence:
            expression = sp.cancel(element.as_expr())
            numerator, denominator = sp.fraction(expression)
            normalized.append(
                (
                    sp.Poly(
                        sp.expand(numerator),
                        fiber,
                        domain=sp.QQ.frac_field(*parents) if parents else sp.QQ,
                    ),
                    sp.Poly(
                        sp.expand(denominator),
                        fiber,
                        domain=sp.QQ.frac_field(*parents) if parents else sp.QQ,
                    ),
                )
            )
        result = tuple(normalized)
        CACHE.fiber_sturm_data.put(cache_key, result)
        return result

    @cached_property
    def _compiled_sturm_elements(self) -> tuple[CompiledSturmElement, ...]:
        """Compile normalized Sturm elements once for repeated endpoint evaluation."""
        cache_key = ("compiled-fiber-sturm", self._generic_sturm_family_identity)
        cached = CACHE.fiber_sturm_data.get(cache_key)
        if cached is not None:
            return cached  # type: ignore[return-value]
        from .signs import _sparse_qq_poly

        parents = self.variables[:-1]
        compiled = []
        for source, (numerator, denominator) in zip(
            self._squarefree_sturm_sequence, self._normalized_sturm_elements, strict=True
        ):
            numerator_coeffs = tuple(sp.sympify(c) for c in numerator.all_coeffs())
            denominator_coeffs = tuple(sp.sympify(c) for c in denominator.all_coeffs())
            numerator_sparse = tuple(_sparse_qq_poly(c, parents) for c in numerator_coeffs)
            denominator_sparse = tuple(_sparse_qq_poly(c, parents) for c in denominator_coeffs)
            compiled.append(
                CompiledSturmElement(
                    numerator_coeffs,
                    denominator_coeffs,
                    numerator.degree(),
                    denominator.degree(),
                    source.degree(),
                    (
                        tuple(value for value in numerator_sparse if value is not None)
                        if all(value is not None for value in numerator_sparse)
                        else None
                    ),
                    (
                        tuple(value for value in denominator_sparse if value is not None)
                        if all(value is not None for value in denominator_sparse)
                        else None
                    ),
                )
            )
        result = tuple(compiled)
        CACHE.fiber_sturm_data.put(cache_key, result)
        return result

    def _parent_rational_function_sign(
        self, numerator: sp.Expr, denominator: sp.Expr = sp.S.One
    ) -> int:
        """Sign a normalized parent rational function through compiled tower data."""
        from .signs import _compiled_sparse_tower_sign, _sparse_qq_poly, sign_at_sample

        parents = self.variables[:-1]
        numerator_expr = sp.expand(numerator)
        denominator_expr = sp.expand(denominator)
        parent_key = tuple(sample_identity_key(sample) for sample in self.parent_samples)
        sign_key = (
            "parent-rational-function-sign",
            parents,
            parent_key,
            expr_key(numerator_expr),
            expr_key(denominator_expr),
        )
        cached_sign = CACHE.parent_signs.get(sign_key)
        if cached_sign is not None:
            return int(cached_sign)

        def compiled_sign(expression: sp.Expr, *, scalar_direct: bool = False) -> int:
            if scalar_direct and not expression.free_symbols:
                return 1 if expression > 0 else -1 if expression < 0 else 0
            sparse_key = ("sparse-qq-poly", expr_key(expression), parents)
            sparse = CACHE.compiled_polys.get(sparse_key)
            if sparse is None:
                sparse = _sparse_qq_poly(expression, parents)
                if sparse is not None:
                    CACHE.compiled_polys.put(sparse_key, sparse)
            if sparse is not None:
                # Interval/tower reduction can certify every nonzero sign and many
                # exact zeros without invoking the substantially more expensive
                # fiber-membership machinery.  Only ask for a separate zero
                # certificate when the compiled tower path is inconclusive.
                result = _compiled_sparse_tower_sign(sparse, parents, self.parent_samples)
                if result is not None:
                    return result
                if (
                    self.parent_samples
                    and isinstance(self.parent_samples[-1], AlgebraicRoot)
                    and self.parent_samples[-1].fiber_context is not None
                ):
                    zero_poly_key = ("qq-poly", expr_key(expression), parents)
                    zero_poly = CACHE.compiled_polys.get(zero_poly_key)
                    if zero_poly is None:
                        zero_poly = sp.Poly(expression, *parents, domain=sp.QQ)
                        CACHE.compiled_polys.put(zero_poly_key, zero_poly)
                    from .comparison import _fiber_poly_zero_at_root

                    if _fiber_poly_zero_at_root(zero_poly, self.parent_samples[-1]):
                        return 0
            # Preserve the established exact path for unsupported coefficient rings.
            poly_key_ = ("qq-poly", expr_key(expression), parents)
            poly = CACHE.compiled_polys.get(poly_key_)
            if poly is None:
                poly = sp.Poly(expression, *parents, domain=sp.QQ)
                CACHE.compiled_polys.put(poly_key_, poly)
            return sign_at_sample(poly, self.parent_samples)

        numerator_sign = compiled_sign(numerator_expr)
        if numerator_sign == 0:
            CACHE.parent_signs.put(sign_key, 0)
            return 0
        denominator_sign = compiled_sign(denominator_expr, scalar_direct=True)
        if denominator_sign == 0:
            raise ArithmeticError("Sturm coefficient denominator vanishes at the parent sample")
        result = numerator_sign * denominator_sign
        CACHE.parent_signs.put(sign_key, result)
        return result

    def _parent_sparse_rational_function_sign(
        self,
        numerator: dict[tuple[int, ...], sp.Rational],
        denominator: dict[tuple[int, ...], sp.Rational],
    ) -> int:
        """Sign an already-compiled parent rational function without Expr→Poly conversion."""
        from .signs import _compiled_sparse_tower_sign, sign_at_sample

        parents = self.variables[:-1]
        parent_key = tuple(sample_identity_key(sample) for sample in self.parent_samples)
        numerator_key = tuple(sorted(numerator.items()))
        denominator_key = tuple(sorted(denominator.items()))
        sign_key = (
            "parent-sparse-rational-function-sign",
            parents,
            parent_key,
            numerator_key,
            denominator_key,
        )
        cached_sign = CACHE.parent_signs.get(sign_key)
        if cached_sign is not None:
            return int(cached_sign)

        def compiled_sign(
            sparse: dict[tuple[int, ...], sp.Rational], *, scalar_direct: bool = False
        ) -> int:
            if not sparse:
                return 0
            if scalar_direct and all(not any(powers) for powers in sparse):
                scalar = sparse.get((0,) * len(parents), sp.S.Zero)
                return 1 if scalar > 0 else -1 if scalar < 0 else 0
            result = _compiled_sparse_tower_sign(sparse, parents, self.parent_samples)
            if result is not None:
                return result
            if (
                self.parent_samples
                and isinstance(self.parent_samples[-1], AlgebraicRoot)
                and self.parent_samples[-1].fiber_context is not None
            ):
                zero_poly = sp.Poly.from_dict(sparse, parents, domain=sp.QQ)
                from .comparison import _fiber_poly_zero_at_root

                if _fiber_poly_zero_at_root(zero_poly, self.parent_samples[-1]):
                    return 0
            poly = sp.Poly.from_dict(sparse, parents, domain=sp.QQ)
            return sign_at_sample(poly, self.parent_samples)

        numerator_sign = compiled_sign(numerator)
        if numerator_sign == 0:
            CACHE.parent_signs.put(sign_key, 0)
            return 0
        denominator_sign = compiled_sign(denominator, scalar_direct=True)
        if denominator_sign == 0:
            raise ArithmeticError("Sturm coefficient denominator vanishes at the parent sample")
        result = numerator_sign * denominator_sign
        CACHE.parent_signs.put(sign_key, result)
        return result

    def _parent_sparse_rational_function_signs(
        self,
        values: tuple[
            tuple[dict[tuple[int, ...], sp.Rational], dict[tuple[int, ...], sp.Rational]], ...
        ],
    ) -> tuple[int, ...]:
        """Sign a compiled endpoint family against one prepared parent tower."""
        from .signs import _compiled_sparse_tower_signs

        parents = self.variables[:-1]
        parent_key = tuple(sample_identity_key(sample) for sample in self.parent_samples)
        local: dict[tuple[object, object], int] = {}
        signs: list[int | None] = [None] * len(values)
        pending_indices = []
        pending_numerators = []

        # Consume the persistent sign cache first, and batch only genuinely new
        # numerators.  Denominators are usually shared/scalar and remain on the
        # ordinary cached exact path below.
        for index, (numerator, denominator) in enumerate(values):
            numerator_key = tuple(sorted(numerator.items()))
            denominator_key = tuple(sorted(denominator.items()))
            key = (numerator_key, denominator_key)
            sign = local.get(key)
            if sign is not None:
                signs[index] = sign
                continue
            sign_key = (
                "parent-sparse-rational-function-sign",
                parents,
                parent_key,
                numerator_key,
                denominator_key,
            )
            cached = CACHE.parent_signs.get(sign_key)
            if cached is not None:
                sign = int(cached)
                local[key] = sign
                signs[index] = sign
                continue
            pending_indices.append(index)
            pending_numerators.append(numerator)

        if pending_numerators:
            numerator_signs = _compiled_sparse_tower_signs(
                pending_numerators, parents, self.parent_samples, max_rounds=0
            )
            for index, numerator_sign in zip(pending_indices, numerator_signs, strict=True):
                if numerator_sign is None:
                    continue
                numerator, denominator = values[index]
                if numerator_sign == 0:
                    sign = 0
                else:
                    # Reuse the established exact denominator path.  Calling the
                    # full helper here also publishes the normal persistent cache.
                    # For nonzero numerators it will repeat a cheap tower sign, so
                    # publish the numerator result separately via the local batch
                    # only when the denominator is the scalar +1 fast case.
                    scalar = denominator.get((0,) * len(parents))
                    if len(denominator) == 1 and scalar is not None and scalar != 0:
                        sign = numerator_sign * (1 if scalar > 0 else -1)
                    else:
                        continue
                numerator_key = tuple(sorted(numerator.items()))
                denominator_key = tuple(sorted(denominator.items()))
                key = (numerator_key, denominator_key)
                sign_key = (
                    "parent-sparse-rational-function-sign",
                    parents,
                    parent_key,
                    numerator_key,
                    denominator_key,
                )
                local[key] = sign
                signs[index] = sign
                CACHE.parent_signs.put(sign_key, sign)

        for index, (numerator, denominator) in enumerate(values):
            if signs[index] is not None:
                continue
            key = (tuple(sorted(numerator.items())), tuple(sorted(denominator.items())))
            sign = local.get(key)
            if sign is None:
                sign = self._parent_sparse_rational_function_sign(numerator, denominator)
                local[key] = sign
            signs[index] = sign
        return tuple(int(sign) for sign in signs if sign is not None)

    def _parent_rational_function_signs(
        self, values: tuple[tuple[sp.Expr, sp.Expr], ...]
    ) -> tuple[int, ...]:
        """Sign an endpoint family while sharing repeated parent rational functions."""
        local: dict[tuple[object, object], int] = {}
        signs = []
        for numerator, denominator in values:
            key = (expr_key(sp.expand(numerator)), expr_key(sp.expand(denominator)))
            sign = local.get(key)
            if sign is None:
                sign = self._parent_rational_function_sign(numerator, denominator)
                local[key] = sign
            signs.append(sign)
        return tuple(signs)

    @staticmethod
    def _eval_coefficient_poly_at_rational(poly: sp.Poly, value: sp.Rational) -> sp.Expr:
        q = sp.Rational(value)
        coefficients = poly.all_coeffs()
        if not coefficients:
            return sp.S.Zero
        result = coefficients[0]
        for coefficient in coefficients[1:]:
            result = result * q + coefficient
        domain = poly.domain
        if hasattr(domain, "to_sympy"):
            try:
                return sp.sympify(domain.to_sympy(result))
            except (TypeError, ValueError):
                pass
        return sp.sympify(result)

    @staticmethod
    def _variations(signs: tuple[int, ...] | list[int]) -> int:
        nonzero = [sign for sign in signs if sign]
        return sum(a != b for a, b in zip(nonzero, nonzero[1:], strict=False))

    def _eval_sturm_element_at_rational(self, poly: sp.Poly, value: sp.Rational) -> sp.Expr:
        """Evaluate in the fiber coordinate without constructing a substituted expression."""
        q = sp.Rational(value)
        coefficients = poly.all_coeffs()
        if not coefficients:
            return sp.S.Zero
        result = coefficients[0]
        for coefficient in coefficients[1:]:
            result = result * q + coefficient
        domain = poly.domain
        if hasattr(domain, "to_sympy"):
            try:
                return sp.sympify(domain.to_sympy(result))
            except (TypeError, ValueError):
                pass
        return sp.sympify(result)

    def _specialized_sturm_endpoint_cert(
        self, value: sp.Rational | None, *, negative_infinity: bool = False
    ) -> SturmEndpointCert | None:
        """Evaluate Sturm data after exact parent specialization at exceptional sections.

        Generic PRS coefficients over ``QQ(parents)`` may acquire denominators
        that vanish after a degree drop.  In that case specialize the *source
        polynomial first* using existing exact root representations, then form
        the univariate Sturm sequence.  This is local coefficient
        specialization; it does not construct a global primitive element for
        the parent tower.
        """
        substitutions: dict[sp.Symbol, sp.Expr] = {}
        for variable, sample in zip(self.variables[:-1], self.parent_samples, strict=True):
            exact = local_tower_root_expr(sample)
            if exact is None:
                return None
            substitutions[variable] = exact
        sequence_key = ("specialized-fiber-sturm-sequence", self._sturm_identity)
        sequence = CACHE.fiber_sturm_data.get(sequence_key)
        if sequence is None:
            try:
                specialized_expr = sp.expand(self.polynomial.as_expr().subs(substitutions))
                specialized = sp.Poly(
                    specialized_expr, self.fiber_variable, extension=True
                ).sqf_part()
                sequence_list = [specialized]
                derivative = specialized.diff()
                if not derivative.is_zero:
                    sequence_list.append(derivative)
                while len(sequence_list) >= 2:
                    remainder = -sequence_list[-2].rem(sequence_list[-1])
                    if remainder.is_zero:
                        break
                    sequence_list.append(remainder)
                sequence = tuple(sequence_list)
                CACHE.fiber_sturm_data.put(sequence_key, sequence)
            except (
                sp.PolynomialError,
                ValueError,
                TypeError,
                NotImplementedError,
                sp.polys.polyerrors.NotInvertible,
            ):
                return None

        signs: list[int] = []
        for poly in sequence:
            if value is None:
                evaluated = poly.LC()
                if negative_infinity and poly.degree() % 2:
                    evaluated = -evaluated
            else:
                evaluated = poly.eval(sp.Rational(value))
            evaluated = sp.sympify(evaluated)
            if evaluated == 0 or evaluated.is_zero is True:
                signs.append(0)
            elif evaluated.is_positive is True:
                signs.append(1)
            elif evaluated.is_negative is True:
                signs.append(-1)
            else:
                exact_sign = sp.sign(evaluated)
                if exact_sign in (-1, 0, 1):
                    signs.append(int(exact_sign))
                else:
                    return None
        vector = tuple(signs)
        return SturmEndpointCert(vector, self._variations(vector))

    def _sturm_endpoint_cert(
        self, value: sp.Rational | None, *, negative_infinity: bool = False
    ) -> SturmEndpointCert:
        """Return the shared exact sign vector and variation at a Sturm endpoint."""
        if value is None:
            endpoint = ("infinity", -1 if negative_infinity else 1)
        else:
            endpoint = ("rational", sp.Rational(value))
        cache_key = ("fiber-sturm-endpoint", self._sturm_identity, endpoint)
        cached = CACHE.sturm_endpoint_certs.get(cache_key)
        if cached is not None:
            return cached  # type: ignore[return-value]

        quotient_signs = self._tower_quotient_sturm_signs_at(
            value, negative_infinity=negative_infinity
        )
        if quotient_signs is None:
            quotient_signs = self._quotient_sturm_signs_at(
                value, negative_infinity=negative_infinity
            )
        if quotient_signs is not None:
            cert = SturmEndpointCert(quotient_signs, self._variations(quotient_signs))
            CACHE.sturm_endpoint_certs.put(cache_key, cert)
            return cert

        rational_functions = []
        sparse_functions = []
        all_sparse = True
        parity = []
        for compiled in self._compiled_sturm_elements:
            if value is None:
                numerator = compiled.numerator_coeffs[0]
                denominator = compiled.denominator_coeffs[0]
                sparse_pair = (
                    (compiled.numerator_sparse_coeffs[0], compiled.denominator_sparse_coeffs[0])
                    if compiled.numerator_sparse_coeffs is not None
                    and compiled.denominator_sparse_coeffs is not None
                    else None
                )
                parity.append(-1 if negative_infinity and compiled.source_degree % 2 else 1)
            else:
                numerator, denominator = compiled.at(sp.Rational(value))
                sparse_pair = compiled.sparse_at(sp.Rational(value))
                parity.append(1)
            rational_functions.append((numerator, denominator))
            if sparse_pair is None:
                all_sparse = False
            else:
                sparse_functions.append(sparse_pair)
        try:
            parent_signs = (
                self._parent_sparse_rational_function_signs(tuple(sparse_functions))
                if all_sparse
                else self._parent_rational_function_signs(tuple(rational_functions))
            )
        except ArithmeticError as exc:
            if "denominator vanishes" not in str(exc):
                raise
            specialized_cert = self._specialized_sturm_endpoint_cert(
                value, negative_infinity=negative_infinity
            )
            if specialized_cert is None:
                raise
            CACHE.sturm_endpoint_certs.put(cache_key, specialized_cert)
            return specialized_cert
        sign_vector = tuple(
            sign * factor for sign, factor in zip(parent_signs, parity, strict=True)
        )
        cert = SturmEndpointCert(sign_vector, self._variations(sign_vector))
        CACHE.sturm_endpoint_certs.put(cache_key, cert)
        return cert

    def _sturm_signs_at(
        self, value: sp.Rational | None, *, negative_infinity: bool = False
    ) -> tuple[int, ...]:
        return self._sturm_endpoint_cert(value, negative_infinity=negative_infinity).signs

    def _sturm_variation_at(
        self, value: sp.Rational | None, *, negative_infinity: bool = False
    ) -> int:
        return self._sturm_endpoint_cert(value, negative_infinity=negative_infinity).variations

    def _intvl_cert_key(self, left: sp.Rational, right: sp.Rational) -> tuple[object, ...]:
        return ("fiber-root-interval", self._sturm_identity, sp.Rational(left), sp.Rational(right))

    def _ranked_node_key(self, left: sp.Rational, right: sp.Rational) -> tuple[object, ...]:
        return (
            "fiber-ranked-partition",
            self._sturm_identity,
            sp.Rational(left),
            sp.Rational(right),
        )

    def _boundary_rank_key(self, value: sp.Rational) -> tuple[object, ...]:
        return ("fiber-boundary-root-rank", self._sturm_identity, sp.Rational(value))

    def _boundary_cert_key(self, value: sp.Rational) -> tuple[object, ...]:
        return ("fiber-ranked-boundary", self._sturm_identity, sp.Rational(value))

    def _remember_boundary(
        self, value: sp.Rational, rank: int, sturm: SturmEndpointCert | None = None
    ) -> RankedBoundaryCert:
        """Publish one ranked partition boundary and its establishing Sturm data."""
        value = sp.Rational(value)
        key = self._boundary_cert_key(value)
        previous = CACHE.ranked_boundary_certs.get(key)
        if (
            isinstance(previous, RankedBoundaryCert)
            and previous.sturm is not None
            and sturm is None
        ):
            cert = previous
        else:
            cert = RankedBoundaryCert(int(rank), sturm)
            CACHE.ranked_boundary_certs.put(key, cert)
        CACHE.boundary_root_ranks.put(self._boundary_rank_key(value), int(rank))
        return cert

    def _boundary_cert(self, value: sp.Rational) -> RankedBoundaryCert | None:
        cached = CACHE.ranked_boundary_certs.get(self._boundary_cert_key(sp.Rational(value)))
        if isinstance(cached, RankedBoundaryCert):
            return cached
        rank = CACHE.boundary_root_ranks.get(self._boundary_rank_key(sp.Rational(value)))
        if rank is None:
            return None
        return self._remember_boundary(sp.Rational(value), int(rank))

    def _remember_ranked_node(
        self, left: sp.Rational, right: sp.Rational, first_index: int, root_count: int
    ) -> RankedPartitionNode:
        node = RankedPartitionNode(
            RationalInterval(sp.Rational(left), sp.Rational(right)),
            int(first_index),
            int(first_index) + int(root_count) - 1,
        )
        CACHE.ranked_partition_nodes.put(self._ranked_node_key(left, right), node)
        self._remember_boundary(left, int(first_index))
        self._remember_boundary(right, int(first_index) + int(root_count))
        return node

    def _ranked_node(self, left: sp.Rational, right: sp.Rational) -> RankedPartitionNode | None:
        cached = CACHE.ranked_partition_nodes.get(self._ranked_node_key(left, right))
        return cached if isinstance(cached, RankedPartitionNode) else None

    def _remember_intvl_count(self, left: sp.Rational, right: sp.Rational, root_count: int) -> None:
        CACHE.root_intvl_certs.put(self._intvl_cert_key(left, right), int(root_count))

    def _rec_intvl_split(
        self,
        left: sp.Rational,
        split_point: sp.Rational,
        right: sp.Rational,
        left_root_count: int,
        total_root_count: int,
    ) -> None:
        """Persist both children of a certified fiber isolation-tree split."""
        right_root_count = int(total_root_count) - int(left_root_count)
        self._remember_intvl_count(left, split_point, left_root_count)
        self._remember_intvl_count(split_point, right, right_root_count)
        self._remember_intvl_count(left, right, total_root_count)
        CACHE.root_intvl_splits.put(
            self._intvl_cert_key(left, right),
            (sp.Rational(split_point), int(left_root_count), int(right_root_count)),
        )
        parent_node = self._ranked_node(left, right)
        if parent_node is not None:
            first_index = parent_node.first_index
            if left_root_count:
                self._remember_ranked_node(left, split_point, first_index, int(left_root_count))
            else:
                self._remember_boundary(split_point, first_index)
            if right_root_count:
                self._remember_ranked_node(
                    split_point, right, first_index + int(left_root_count), right_root_count
                )
            else:
                self._remember_boundary(split_point, first_index + int(left_root_count))

    def _root_index_intvl_key(self, root_index: int) -> tuple[object, ...]:
        return ("fiber-root-index-interval", self._sturm_identity, int(root_index))

    def _remember_root_rank_cert(
        self, root_index: int, intvl: RationalInterval, local_rank: int, node_root_count: int
    ) -> None:
        key = ("fiber-root-rank", self._sturm_identity, int(root_index))
        cached = CACHE.root_rank_certs.get(key)
        if cached is None or intvl.width < cached.interval.width:
            CACHE.root_rank_certs.put(
                key,
                RootRankCert(int(root_index), intvl, int(local_rank), int(node_root_count)),
            )

    def _remember_root_index_intvl(self, root_index: int, intvl: RationalInterval) -> None:
        key = self._root_index_intvl_key(root_index)
        cached = CACHE.root_index_intvls.get(key)
        if cached is None or intvl.width < cached.width:
            CACHE.root_index_intvls.put(key, intvl)
        self._remember_root_rank_cert(root_index, intvl, 0, 1)

    def root_rank_cert(self, root_index: int) -> RootRankCert | None:
        """Return the strongest exact-rank partition certificate for a fiber root."""
        cached = CACHE.root_rank_certs.get(
            ("fiber-root-rank", self._sturm_identity, int(root_index))
        )
        return cached if isinstance(cached, RootRankCert) else None

    def root_on_or_below(self, root_index: int, value: sp.Rational) -> bool:
        """Decide whether a ranked root is at or below a rational boundary.

        A stored rank interval answers without a new Sturm endpoint whenever the
        boundary lies outside that interval.  Only a boundary cutting through
        the current root node requires a fresh endpoint certificate.
        """
        value = sp.Rational(value)
        boundary = self._boundary_cert(value)
        if boundary is not None:
            return int(root_index) < boundary.root_rank
        cert = self.root_rank_cert(root_index)
        if cert is not None:
            if value < cert.interval.left:
                return False
            if value >= cert.interval.right:
                return True

            # A rank certificate can describe an ancestor node even after its
            # isolation tree has acquired certified child splits.  Replay those
            # persistent splits before paying for a new arbitrary Sturm endpoint.
            # This is exact: every traversed child count was established when the
            # split was created, and ``local_rank`` selects the unique child that
            # still contains this absolute root rank.
            left, right, local_rank, count = self._descend_intvl_partition(
                cert.interval.left,
                cert.interval.right,
                cert.local_rank,
                cert.node_root_count,
            )
            if left != cert.interval.left or right != cert.interval.right:
                narrowed = RationalInterval(left, right)
                self._remember_root_rank_cert(root_index, narrowed, local_rank, count)
                if count == 1:
                    self._remember_root_index_intvl(root_index, narrowed)
                if value < left:
                    return False
                if value >= right:
                    return True

        best = self.best_root_intvl(root_index)
        if best is not None:
            if value < best.left:
                return False
            if value >= best.right:
                return True
        return self.roots_left_of(value) > int(root_index)

    def best_root_intvl(self, root_index: int) -> RationalInterval | None:
        """Return the narrowest persistent interval known for a fiber-root rank."""
        cached = CACHE.root_index_intvls.get(self._root_index_intvl_key(root_index))
        return cached if isinstance(cached, RationalInterval) else None

    def _descend_intvl_partition(
        self, left: sp.Rational, right: sp.Rational, local_rank: int, count: int
    ) -> tuple[sp.Rational, sp.Rational, int, int]:
        """Descend previously certified splits without creating new endpoints."""
        while count > 1:
            split = CACHE.root_intvl_splits.get(self._intvl_cert_key(left, right))
            if split is None:
                break
            split_point, left_count, right_count = split
            if local_rank < left_count:
                right, count = split_point, left_count
            else:
                left = split_point
                local_rank -= left_count
                count = right_count
        return left, right, local_rank, count

    def root_count(self, left: sp.Rational, right: sp.Rational) -> int:
        """Count fiber roots, consulting the persistent isolation tree first."""
        left, right = sp.Rational(left), sp.Rational(right)
        if left > right:
            left, right = right, left
        intvl_key = self._intvl_cert_key(left, right)
        cached_count = CACHE.root_intvl_certs.get(intvl_key)
        if cached_count is not None:
            return int(cached_count)
        left_boundary = self._boundary_cert(left)
        right_boundary = self._boundary_cert(right)
        if left_boundary is not None and right_boundary is not None:
            root_count = right_boundary.root_rank - left_boundary.root_rank
            CACHE.root_intvl_certs.put(intvl_key, root_count)
            return root_count
        # A count necessarily establishes both endpoint variations.  Promote
        # those results immediately to absolute ranked-boundary certificates so
        # later root-order queries never recompute the same Sturm endpoints.
        minus_inf = self._sturm_variation_at(None, negative_infinity=True)
        left_endpoint = self._sturm_endpoint_cert(left)
        right_endpoint = self._sturm_endpoint_cert(right)
        left_rank = minus_inf - left_endpoint.variations
        right_rank = minus_inf - right_endpoint.variations
        self._remember_boundary(left, left_rank, left_endpoint)
        self._remember_boundary(right, right_rank, right_endpoint)
        root_count = right_rank - left_rank
        CACHE.root_intvl_certs.put(intvl_key, int(root_count))
        return int(root_count)

    def roots_left_of(self, value: sp.Rational) -> int:
        """Count roots through a ranked boundary, certifying it only when new."""
        value = sp.Rational(value)
        boundary = self._boundary_cert(value)
        if boundary is not None:
            return boundary.root_rank
        minus_inf = self._sturm_variation_at(None, negative_infinity=True)
        endpoint = self._sturm_endpoint_cert(value)
        rank = minus_inf - endpoint.variations
        self._remember_boundary(value, int(rank), endpoint)
        return int(rank)

    def is_nullified_at_parent(self) -> bool:
        """Return whether the fiber polynomial is identically zero at this parent section.

        This is a section-specific degree-drop certificate.  Generic fraction-field
        arithmetic must not manufacture fiber roots from coefficients that all vanish
        at the selected parent point.
        """
        key = ("fiber-nullified-at-parent", self._sturm_identity)
        cached = CACHE.fiber_sturm_data.get(key)
        if cached is not None:
            return bool(cached)
        from .signs import sign_at_sample

        parents = self.variables[:-1]
        try:
            # Keep algebraic constants in the coefficient domain instead of forcing
            # the parent variables through QQ(...).  At exceptional sections a
            # perfectly valid coefficient can contain, for example, z - sqrt(3).
            fiber = sp.Poly(self.polynomial.as_expr(), self.fiber_variable)
            nullified = True
            for coefficient in fiber.all_coeffs():
                if parents:
                    coefficient_poly = sp.Poly(coefficient, *parents, extension=True)
                    coefficient_sign = sign_at_sample(coefficient_poly, self.parent_samples)
                else:
                    coefficient_sign = self._parent_rational_function_sign(coefficient)
                if coefficient_sign != 0:
                    nullified = False
                    break
        except (
            sp.PolynomialError,
            sp.polys.polyerrors.DomainError,
            ArithmeticError,
            ValueError,
            TypeError,
        ):
            # Inconclusive is not a nullification certificate.
            nullified = False
        CACHE.fiber_sturm_data.put(key, nullified)
        return nullified

    def total_real_roots(self) -> int:
        """Return the number of distinct real fiber roots over the certified parent point."""
        minus_inf = self._sturm_variation_at(None, negative_infinity=True)
        plus_inf = self._sturm_variation_at(None, negative_infinity=False)
        return minus_inf - plus_inf

    def isolate_all_roots(self) -> tuple[RationalInterval, ...]:
        """Isolate every real fiber root, reusing the shared root-set certificate."""
        root_set_key = ("fiber-root-set", self._sturm_identity)
        cached = CACHE.root_sets.get(root_set_key)
        if cached is not None:
            return cached  # type: ignore[return-value]
        total = self.total_real_roots()
        if total <= 0:
            CACHE.root_sets.put(root_set_key, ())
            return ()
        bound = sp.Integer(1)
        for _ in range(128):
            left, right = -sp.Rational(bound), sp.Rational(bound)
            if self.root_count(left, right) == total:
                break
            bound *= 2
        else:
            raise ArithmeticError("could not bound all tower fiber roots")
        initial_intvl = RationalInterval(left, right)
        self._remember_ranked_node(left, right, 0, total)
        for index in range(total):
            self._remember_root_rank_cert(index, initial_intvl, index, total)
        roots = tuple(self.isolate_root(index, left, right, steps=0) for index in range(total))
        CACHE.root_sets.put(root_set_key, roots)
        return roots

    def isolate_root(
        self, root_index: int, left: sp.Rational, right: sp.Rational, *, steps: int = 1
    ) -> RationalInterval:
        """Isolate and refine a fiber root using tower-aware Sturm root counts."""
        left, right = sp.Rational(left), sp.Rational(right)
        rank_cert = self.root_rank_cert(root_index)
        if (
            rank_cert is not None
            and left <= rank_cert.interval.left
            and rank_cert.interval.right <= right
        ):
            left, right = rank_cert.interval.left, rank_cert.interval.right
            local_rank = rank_cert.local_rank
            count = rank_cert.node_root_count
            if self._ranked_node(left, right) is None:
                self._remember_ranked_node(left, right, int(root_index) - int(local_rank), count)
        else:
            cached_intvl = self.best_root_intvl(root_index)
            if (
                cached_intvl is not None
                and left <= cached_intvl.left
                and cached_intvl.right <= right
            ):
                left, right = cached_intvl.left, cached_intvl.right
            local_rank = int(root_index) - self.roots_left_of(left)
            count = self.root_count(left, right)
        if not 0 <= local_rank < count:
            raise ArithmeticError("requested fiber root is outside its certificate interval")
        left, right, local_rank, count = self._descend_intvl_partition(
            left, right, local_rank, count
        )
        self._remember_root_rank_cert(root_index, RationalInterval(left, right), local_rank, count)
        if count == 1:
            try:
                if self.sign_at_rational(right) == 0:
                    result = RationalInterval(right, right)
                    self._remember_root_index_intvl(root_index, result)
                    return result
            except (ArithmeticError, ValueError):
                pass
        for _ in range(80):
            if count == 1:
                break
            known_split = CACHE.root_intvl_splits.get(self._intvl_cert_key(left, right))
            if known_split is not None:
                mid, left_count, _right_count = known_split
            else:
                mid = sp.Rational(left + right, 2)
                left_count = self.root_count(left, mid)
            self._rec_intvl_split(left, mid, right, left_count, count)
            next_count = left_count if local_rank < left_count else count - left_count
            record_refinement_request("root isolation", advanced=True, decisive=next_count == 1)
            if local_rank < left_count:
                right = mid
                count = left_count
            else:
                left = mid
                local_rank -= left_count
                count -= left_count
            self._remember_root_rank_cert(
                root_index, RationalInterval(left, right), local_rank, count
            )
        else:
            raise ArithmeticError("could not isolate requested fiber root by Sturm counts")
        if count == 1:
            midpoint = sp.Rational(left + right, 2)
            try:
                if self.sign_at_rational(midpoint) == 0:
                    result = RationalInterval(midpoint, midpoint)
                    self._remember_root_index_intvl(root_index, result)
                    return result
            except (ArithmeticError, ValueError):
                pass
        for _ in range(max(steps, 0)):
            known_split = CACHE.root_intvl_splits.get(self._intvl_cert_key(left, right))
            mid = known_split[0] if known_split is not None else sp.Rational(left + right, 2)
            try:
                if self.sign_at_rational(mid) == 0:
                    result = RationalInterval(mid, mid)
                    self._remember_root_index_intvl(root_index, result)
                    return result
            except (ArithmeticError, ValueError):
                pass
            left_count = (
                int(known_split[1]) if known_split is not None else self.root_count(left, mid)
            )
            self._rec_intvl_split(left, mid, right, left_count, 1)
            record_refinement_request("root isolation", advanced=True, decisive=False)
            if left_count:
                right = mid
            else:
                left = mid
        result = RationalInterval(left, right)
        self._remember_root_index_intvl(root_index, result)
        return result

    def squarefree_sign_at_rational(self, value: sp.Rational) -> int:
        """Return the sign of the fiber-squarefree part at a rational coordinate.

        Removing repeated fiber factors makes interval bisection sign-changing
        even when the represented section has even multiplicity.  Coefficients
        remain rational functions of the parent variables; evaluation is then
        delegated recursively to the certified parent tower.
        """
        from .signs import sign_at_sample

        parents = self.variables[:-1]
        try:
            fiber_poly = self._squarefree_fiber_poly
            reduced_expr = sp.cancel(
                self._eval_sturm_element_at_rational(fiber_poly, sp.Rational(value))
            )
            numerator, denominator = sp.fraction(reduced_expr)
            numerator_sign = sign_at_sample(
                sp.Poly(sp.expand(numerator), *parents, domain=sp.QQ), self.parent_samples
            )
            denominator_sign = sign_at_sample(
                sp.Poly(sp.expand(denominator), *parents, domain=sp.QQ), self.parent_samples
            )
            return numerator_sign * denominator_sign
        except (
            sp.PolynomialError,
            sp.polys.polyerrors.CoercionFailed,
            sp.polys.polyerrors.DomainError,
            ValueError,
            TypeError,
        ):
            return self.sign_at_rational(value)


@total_ordering
@dataclass(frozen=True)
class AlgebraicRoot:
    """A real algebraic root represented by a polynomial, expression, and isolating interval."""

    polynomial: sp.Poly
    interval: RationalInterval
    root_index: int
    multiplicity: int = 1
    root_expr: sp.Expr | None = None
    fiber_context: FiberRootContext | None = None

    def __post_init__(self) -> None:
        if self.polynomial.is_multivariate:
            raise ValueError("AlgebraicRoot requires a univariate polynomial")
        if self.polynomial.degree() <= 0:
            raise ValueError("AlgebraicRoot requires a positive-degree polynomial")
        if self.root_index < 0:
            raise ValueError("root_index must be nonnegative")
        if self.multiplicity < 1:
            raise ValueError("multiplicity must be positive")

    @property
    def variable(self) -> sp.Symbol:
        return self.polynomial.gens[0]

    def as_expr(self) -> sp.Expr:
        if _TOWER_EXPRESSION_GUARD.get():
            CACHE.stats.tower_escapes += 1
        if self.root_expr is not None:
            return self.root_expr
        try:
            ordered = sp.real_roots(self.polynomial.as_expr())
            interval_roots: list[sp.Expr] = []
            for candidate in ordered:
                if (
                    compare_exact_reals(candidate, self.interval.left) >= 0
                    and compare_exact_reals(candidate, self.interval.right) <= 0
                    and (
                        not interval_roots
                        or compare_exact_reals(interval_roots[-1], candidate) != 0
                    )
                ):
                    interval_roots.append(candidate)
            if len(interval_roots) == 1:
                return interval_roots[0]

            ordered = sorted(ordered, key=cmp_to_key(compare_exact_reals))
            roots: list[sp.Expr] = []
            for candidate in ordered:
                if not roots or compare_exact_reals(roots[-1], candidate) != 0:
                    roots.append(candidate)
            if self.root_index < len(roots):
                return roots[self.root_index]
        except (NotImplementedError, sp.PolynomialError, ValueError, TypeError):
            pass

        # SymPy cannot construct RootOf objects over every algebraic coefficient
        # domain.  For low-degree fibers, recover a native radical only when its
        # real identity is certified by this root's isolating interval.  This is
        # presentation-only: the interval remains the authoritative root identity.
        if self.polynomial.degree() <= 4:
            try:
                radicals = sp.roots(self.polynomial.as_expr(), self.variable)
                candidates = []
                for expr, multiplicity in radicals.items():
                    if expr.is_real is not True:
                        continue
                    left_cmp = compare_exact_reals(expr, self.interval.left)
                    right_cmp = compare_exact_reals(expr, self.interval.right)
                    if left_cmp >= 0 and right_cmp <= 0:
                        candidates.extend([sp.simplify(expr)] * int(multiplicity))
                if len(candidates) == 1:
                    return candidates[0]
            except (
                NotImplementedError,
                sp.PolynomialError,
                ValueError,
                TypeError,
            ):
                pass

        # Keep an exact ordered-root selector when no readable exact presentation
        # can be certified.
        from ..reconstruct.root_functions import root_of

        return root_of(
            self.polynomial.as_expr(),
            self.variable,
            sp.Integer(self.root_index),
        )

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, (RationalSample, AlgebraicRoot)):
            return NotImplemented
        from .comparison import compare_samples

        return compare_samples(self, other) < 0

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, (RationalSample, AlgebraicRoot)):
            return False
        from .comparison import compare_samples

        return compare_samples(self, other) == 0


Sample = RationalSample | AlgebraicRoot


def local_tower_root_expr(sample: Sample) -> sp.Expr | None:
    """Build a root expression recursively within its existing triangular tower.

    This is intentionally local: each fiber is specialized only at its own
    certified parents.  It does not construct a primitive element for the full
    sample tuple.
    """
    if isinstance(sample, RationalSample):
        return sample.value
    if sample.root_expr is not None:
        return sample.root_expr
    if sample.fiber_context is None:
        if sample.polynomial.domain in (sp.ZZ, sp.QQ):
            try:
                return sp.CRootOf(sample.polynomial.as_expr(), sample.root_index)
            except (sp.PolynomialError, ValueError, TypeError):
                return None
        return None
    context = sample.fiber_context
    substitutions: dict[sp.Symbol, sp.Expr] = {}
    for variable, parent in zip(context.variables[:-1], context.parent_samples, strict=True):
        exact = local_tower_root_expr(parent)
        if exact is None:
            return None
        substitutions[variable] = exact
    try:
        specialized = sp.Poly(
            sp.expand(context.polynomial.as_expr().subs(substitutions)),
            context.fiber_variable,
            extension=True,
        )
        if specialized.degree() <= 0 or sample.root_index >= specialized.degree():
            return None
        return sp.CRootOf(specialized.as_expr(), sample.root_index)
    except (
        sp.PolynomialError,
        sp.polys.polyerrors.DomainError,
        sp.polys.polyerrors.NotInvertible,
        ValueError,
        TypeError,
        NotImplementedError,
    ):
        return None


def sample_to_expr(sample: Sample) -> sp.Expr:
    if not isinstance(sample, (RationalSample, AlgebraicRoot)):
        raise TypeError("expected a semialg algebraic Sample object")
    if (
        isinstance(sample, AlgebraicRoot)
        and sample.fiber_context is not None
        and not _TOWER_EXPRESSION_GUARD.get()
    ):
        CACHE.stats.tower_escapes += 1
    return sample.as_expr()
